 test("Forbidden Word: six-round match has exact ordered turns winner and final scores",async({page,browser})=>{
  test.skip(!process.env.E2E_DATABASE_URL);const id=await setup(page),initial=await read(page,id),{tv,context}=await display(page,browser,id);try{const targets=new Set<string>();for(let round=0;round<6;round++){let v=await read(page,id);expect(v.roundNumber).toBe(round+1);expect(v.activeTeamId).toBe(initial.teams[round%2].id);expect(targets.has(v.card!.targetWord)).toBe(false);targets.add(v.card!.targetWord);for(let i=0;i<(round%2===0?2:1);i++){v=await command(page,id,"CORRECT");expect(targets.has(v.card!.targetWord)).toBe(false);targets.add(v.card!.targetWord);}v=await finishRound(page,id);if(round<5){expect(v.phase).toBe("ROUND_INTRO");await command(page,id,"START_ROUND");}}const final=await read(page,id);expect(final).toMatchObject({phase:"FINAL_RESULTS",winnerTeamId:initial.teams[0].id,roundNumber:6});expect(final.teams.map(t=>t.score)).toEqual([6,3]);await expect(tv.getByRole("heading",{name:"فاز فريق ياقوت!",exact:true})).toBeVisible();const key=crypto.randomUUID(),complete=()=>page.request.post("/api/secret-word/"+id+"/commands",{headers:{Origin:origin},data:{key,expectedVersion:final.version,action:{type:"COMPLETE"}}});expect((await Promise.all([complete(),complete()])).map(r=>r.status())).toEqual([200,200]);expect((await read(page,id)).version).toBe(final.version+1);}finally{await context.close();}

